import{c as a,Q as s,j as e,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"How to Actually Prompt Fable 5, Straight From the Team That Built It","description":"","frontmatter":{"url":"https://x.com/cyrilxbt/status/2072706408710058492","title":"How to Actually Prompt Fable 5, Straight From the Team That Built It","author":"cyrilXBT","archived":"2026-07-03T00:00:00.000Z","handle":"@cyrilXBT","published":"2026-07-02T00:00:00.000Z","stats":"220 likes · 30 retweets · 434 bookmarks · 124363 views","tags":["fable5","prompting","ultrathink","ultracode","verification","subagent-delegation","migration-checklist","vision","API"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@cyrilXBT-058492.md","filePath":"research/tweets/2026-07-02-@cyrilXBT-058492.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-07-02-@cyrilXBT-058492.md"};function o(r,t,l,p,c,d){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="how-to-actually-prompt-fable-5-straight-from-the-team-that-built-it-—-cyrilxbt" tabindex="-1">How to Actually Prompt Fable 5, Straight From the Team That Built It — @cyrilXBT <a class="header-anchor" href="#how-to-actually-prompt-fable-5-straight-from-the-team-that-built-it-—-cyrilxbt" aria-label="Permalink to &quot;How to Actually Prompt Fable 5, Straight From the Team That Built It — @cyrilXBT&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/cyrilxbt/status/2072706408710058492" target="_blank" rel="noreferrer">https://x.com/cyrilxbt/status/2072706408710058492</a><strong>作者</strong>：cyrilXBT（@cyrilXBT） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：220 likes · 30 retweets · 434 bookmarks · 124363 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：Anthropic 官方 prompting guide 完整解碼，含 API 級別技術細節、10+ 個直接可用的 prompt 模板，以及 Fable 5 遷移 checklist。</p><h3 id="最大行為變化-回應時間" tabindex="-1">最大行為變化：回應時間 <a class="header-anchor" href="#最大行為變化-回應時間" aria-label="Permalink to &quot;最大行為變化：回應時間&quot;">​</a></h3><ul><li>high effort：單次回應可達數分鐘</li><li>自主 run：可達數小時</li><li><strong>API 遷移警告</strong>：為 Opus 4.8 設定的 timeout 必定太短，需重新審計所有 timeout 設定</li></ul><h3 id="effort-控制方法" tabindex="-1">Effort 控制方法 <a class="header-anchor" href="#effort-控制方法" aria-label="Permalink to &quot;Effort 控制方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>觸發</th><th>效果</th></tr></thead><tbody><tr><td>prompt 含 <code>ultrathink</code></td><td>單次請求</td><td>xhigh 推理 effort</td></tr><tr><td>Claude Code <code>/effort ultracode</code></td><td>整個 session</td><td>xhigh + 自動 dynamic workflow 編排</td></tr><tr><td>API <code>effort</code> 參數</td><td>每次請求</td><td>直接指定</td></tr></tbody></table><p><strong>⚠️ 重要</strong>：<code>ultracode</code> 需要支援 xhigh effort 的模型（Fable 5 / Opus 4.8 / Opus 4.7），Sonnet 4.6 及更早版本不支援。</p><p><strong>Thinking display 設定</strong>：<code>thinking.display = &quot;summarized&quot;</code> 返回可讀摘要；<code>&quot;omitted&quot;</code>（默認）返回空 thinking 欄位。Raw chain of thought 在 Fable 5 永不返回。</p><h3 id="進度驗證-prompt-最關鍵技術" tabindex="-1">進度驗證 Prompt（最關鍵技術） <a class="header-anchor" href="#進度驗證-prompt-最關鍵技術" aria-label="Permalink to &quot;進度驗證 Prompt（最關鍵技術）&quot;">​</a></h3><p>Anthropic 測試：以下措辭幾乎消除長 agentic run 的虛假進度報告，<strong>「audit」語言優於更溫和的等效說法（Anthropic 測試多個版本確認）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before reporting progress, audit each claim against</span></span>
<span class="line"><span>a tool result from this session. Only report work</span></span>
<span class="line"><span>you can point to evidence for. If something is not</span></span>
<span class="line"><span>yet verified, say so explicitly. Report outcomes</span></span>
<span class="line"><span>faithfully: if tests fail, say so with the output.</span></span>
<span class="line"><span>If a step was skipped, state that. When something</span></span>
<span class="line"><span>is done and verified, state it plainly without hedging.</span></span></code></pre></div><p><strong>建議</strong>：寫入 system prompt，對任何超過幾分鐘或涉及 tool 執行的 workflow 都要加。</p><h3 id="主動性問題-proactivity-constraint" tabindex="-1">主動性問題（Proactivity Constraint） <a class="header-anchor" href="#主動性問題-proactivity-constraint" aria-label="Permalink to &quot;主動性問題（Proactivity Constraint）&quot;">​</a></h3><p>Fable 5 比 Opus 4.8 更主動，會採取未被要求的行動（起草 email、建 git 備份分支）。針對所有自動化/無人值守 workflow 的 system prompt 加入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When the user is describing a problem, asking a question,</span></span>
<span class="line"><span>or thinking out loud rather than requesting a change, the</span></span>
<span class="line"><span>deliverable is your assessment. Report your findings and</span></span>
<span class="line"><span>stop. Do not apply a fix until asked. Before running a</span></span>
<span class="line"><span>command that changes system state, including restarts,</span></span>
<span class="line"><span>deletes, or config edits, confirm that the evidence</span></span>
<span class="line"><span>actually supports that specific action.</span></span></code></pre></div><h3 id="記憶系統-prompt" tabindex="-1">記憶系統 Prompt <a class="header-anchor" href="#記憶系統-prompt" aria-label="Permalink to &quot;記憶系統 Prompt&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Maintain a memory system in [folder]. Store one lesson per</span></span>
<span class="line"><span>file with a one-line summary at the top. Record corrections</span></span>
<span class="line"><span>and confirmed approaches alike, including why they mattered.</span></span>
<span class="line"><span>Do not save information already in the repo or chat history.</span></span>
<span class="line"><span>Update existing notes rather than creating duplicates.</span></span>
<span class="line"><span>Delete notes that have proven incorrect.</span></span></code></pre></div><p>Session 結束時：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reflect on the sessions we have had. Use subagents to</span></span>
<span class="line"><span>identify core themes and lessons, and store them in [folder].</span></span>
<span class="line"><span>Reference [folder] at the start of future sessions.</span></span></code></pre></div><h3 id="final-response-格式指令-長-run-後" tabindex="-1">Final Response 格式指令（長 run 後） <a class="header-anchor" href="#final-response-格式指令-長-run-後" aria-label="Permalink to &quot;Final Response 格式指令（長 run 後）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For your final response after this task: state the outcome</span></span>
<span class="line"><span>first, then the key supporting details. Do not include working</span></span>
<span class="line"><span>abbreviations, internal labels, or arrow chains in the</span></span>
<span class="line"><span>user-facing output. Users need the outcome, the evidence,</span></span>
<span class="line"><span>the risks if any, and the next step.</span></span></code></pre></div><p>→ 將模型內部工作過程與最終用戶看到的輸出分離。</p><h3 id="sub-agent-委派模式" tabindex="-1">Sub-Agent 委派模式 <a class="header-anchor" href="#sub-agent-委派模式" aria-label="Permalink to &quot;Sub-Agent 委派模式&quot;">​</a></h3><p>三條需同時使用的指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Delegate independent subtasks to sub-agents and continue</span></span>
<span class="line"><span>working while they run. Each sub-agent should receive a</span></span>
<span class="line"><span>specific, bounded scope and explicit success criteria.</span></span>
<span class="line"><span>Synthesize sub-agent results only after all have reported.</span></span>
<span class="line"><span>If any sub-agent fails or cannot complete its scope, report</span></span>
<span class="line"><span>that clearly in the synthesis rather than inferring what</span></span>
<span class="line"><span>would have been found.</span></span></code></pre></div><p><strong>關鍵最後一行</strong>：<strong>子代理失敗 = 資訊，不得推斷</strong>。綜合報告必須如實反映失敗。</p><h3 id="安全分類器與-api-錯誤處理" tabindex="-1">安全分類器與 API 錯誤處理 <a class="header-anchor" href="#安全分類器與-api-錯誤處理" aria-label="Permalink to &quot;安全分類器與 API 錯誤處理&quot;">​</a></h3><p><strong>⚠️ 拒絕 = HTTP 200，非錯誤</strong>：</p><ul><li><code>stop_reason: &quot;refusal&quot;</code> 是成功的 API 調用，需獨立於 HTTP status 檢查</li><li>Anthropic 提供 SDK middleware 用於自動 fallback 到 Opus 4.8（prompt-cache 費用在無輸出的拒絕中不計費）</li><li>拒絕率：典型開發者查詢 &lt;5%，但可出現在涉及生物/代碼審查敏感域的正常任務中</li></ul><h3 id="vision-prompting-升級後" tabindex="-1">Vision Prompting（升級後） <a class="header-anchor" href="#vision-prompting-升級後" aria-label="Permalink to &quot;Vision Prompting（升級後）&quot;">​</a></h3><p><strong>關鍵觸發語句</strong>：加入「crop and zoom」觸發 bash 工具處理噪雜圖像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Here is the design target and a screenshot of the current</span></span>
<span class="line"><span>implementation. Use vision to identify differences and</span></span>
<span class="line"><span>generate the changes needed to close the gap. Crop and zoom</span></span>
<span class="line"><span>into any areas where the comparison is unclear before</span></span>
<span class="line"><span>reporting findings.</span></span></code></pre></div><p>Fable 5 可用 vision 評估自己的輸出（設計稿 vs 截圖 → 識別差異），關閉了以前需要人工視覺比對的迴路。</p><h3 id="fable-5-遷移-checklist" tabindex="-1">Fable 5 遷移 Checklist <a class="header-anchor" href="#fable-5-遷移-checklist" aria-label="Permalink to &quot;Fable 5 遷移 Checklist&quot;">​</a></h3><ol><li><strong>Timeouts</strong>：為 Opus 4.8 設定的 timeout 全部太短，必須延長</li><li><strong>Refusal handling</strong>：API response 解析需獨立檢查 <code>stop_reason: &quot;refusal&quot;</code>，設置 Opus 4.8 fallback</li><li><strong>Proactivity constraints</strong>：所有自動化/無人值守 system prompt 加入邊界塊</li><li><strong>Progress verification</strong>：所有超 5 分鐘或涉及 tool 執行的 workflow 加入 audit 指令</li><li><strong>Memory structure</strong>：跨 session workflow 設置 lesson file 結構</li><li><strong>Final response format</strong>：所有直接輸出給用戶的 workflow 加入 outcome-first 指令</li><li><strong>Testing scope</strong>：用至少一個 Opus 4.8 無法完成的任務測試，驗證遷移是否有實質改善</li></ol><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Anthropic 官方 Fable 5 prompting guide 最完整解碼：<code>ultrathink</code>/<code>ultracode</code> 關鍵字、HTTP 200 拒絕處理、「audit」語言驗證效果最佳、子代理失敗禁止推斷、vision crop-and-zoom、7 項遷移 checklist。技術深度最高，直接可套用。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>ultrathink</strong> = prompt 層面的 xhigh effort 觸發；<strong>ultracode</strong> = session 級 xhigh + 自動 dynamic workflow</li><li><strong>「audit」語言</strong>是進度驗證最有效措辭（Anthropic 多版本測試確認）</li><li><strong>子代理失敗 = 資訊</strong>：不得推斷失敗子代理的結果</li><li><strong>API refusal = HTTP 200</strong>：需獨立解析 stop_reason，不是 HTTP 錯誤</li><li>Vision 的「crop and zoom」指令觸發 bash 預處理噪雜圖像</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><code>ultrathink</code>：單次 xhigh prompt 觸發詞</li><li><code>/effort ultracode</code>：session 級 xhigh + 動態 workflow（僅限 Fable/Opus 4.8/4.7）</li><li>拒絕率：&lt;5% 典型開發者查詢</li><li>遷移 7 項 checklist（直接可用）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>本文是本批次工作區可行動性最高的文章之一</li><li>ultrathink/ultracode 在其他文章未見，是操作級新發現</li><li>HTTP 200 refusal 處理是 API 整合的關鍵漏洞點</li><li>Final response format 指令（outcome-first）與 workspace overnight 總結風格高度吻合</li><li>Sub-agent 失敗禁止推斷對齊 core.md 的 unverified_success 閘門</li><li>Vision 部分在本批次 19 篇文章中最有深度</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>10+ 個直接可用模板；遷移 checklist；ultrathink/ultracode 立即可試</td></tr><tr><td>B. 創新性 (20%)</td><td>8.5/10</td><td>ultrathink/ultracode、HTTP 200 refusal、vision crop-and-zoom、子代理失敗規則全是新資訊</td></tr><tr><td>C. 證據品質 (20%)</td><td>8.5/10</td><td>明確引用 Anthropic 官方 guide；audit 語言測試結果；&lt;5% 拒絕率</td></tr><tr><td>D. 技術深度 (15%)</td><td>9/10</td><td>API 級細節、timeout 警告、ultracode 模型要求、thinking.display 設定</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>Vision 部分 Fable 特定；遷移 checklist/驗證塊跨模型通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.7/10</strong></td><td>9×0.3+8.5×0.2+8.5×0.2+9×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：ultrathink/ultracode 可加入 CLAUDE.md；progress verification audit prompt 補充 core.md §TEST；proactivity constraint 和 subagent 失敗規則補充 subagent-strategy.md；HTTP 200 refusal 處理補充 error-handling；final response format 補充 subagent-strategy.md；7 項遷移 checklist 加入 delegation-protocol.md。</p>`,51)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
